"""Exact selected movie/plan settings inventory; never convert settings into proven effects."""
import pathlib,json,gzip,hashlib,collections
Q=pathlib.Path(__file__).resolve().parents[1];R=Q/'composition-recovery'
def raw(p):return gzip.decompress(p.read_bytes()) if p.suffix=='.gz' else p.read_bytes()
def read(p):return json.loads(raw(p))
def sha(b):return hashlib.sha256(b).hexdigest()
s=read(R/'final-word-source-matrix-summary.json');artifacts=[];units=[]
for selected in s['rows']:
 case=selected['fixture'];archive='word-source-refresh-'+case if selected['observationStatus'].startswith('FRESH') else selected['finalSourceQualification']['archive'];m=read(R/archive/'archive-manifest.json');files={x['member']:x for x in m['files']};item=files['matrix/'+case+'-v3-reference.json'];b=raw(Q/item['preserved']);assert sha(b)==item['SHA256'];ref=json.loads(b);binding=selected['versions']['current'].get('binding') or selected['finalSourceQualification']['originalEncodedArtifactBinding'];assert binding['planHash']==ref['planHash'] and binding['videoSHA256']==selected['versions']['current']['videoSHA256'];p=ref['plan'];artifacts.append({'fixture':case,'binding':binding,'referenceSHA256':item['SHA256'],'referenceMember':item['member'],'archive':archive,'selectedSettingCount':len(p['cuts'])})
 for c in p['cuts']:
  if c.get('line',-1)<0:continue
  identity={'binding':binding,'cutIndex':c['index'],'line':c['line'],'start':c['start'],'end':c['end'],'sourceText':c.get('text')};settings={k:c.get(k) for k in ['layout','enter','hold','exit','inDur','outDur','stagger','params','treat','treatP','bg','bgP','cam','camP','decor','trans','transP','transDur','grammar','cinemaV5Direction','cinemaV3Typography','cinemaV3Shot','worldIntent','photoExit','assetScene','locked']};units.append({'settingEvidenceId':sha(json.dumps(identity,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()),'fixture':case,**identity,'settings':settings,'musicContext':{'chapter':c.get('chapter'),'majorAccent':c.get('majorAccent'),'motifState':c.get('motifState'),'worldIntent':c.get('worldIntent')},'semanticState':'UNMEASURED','reason':'Exact selected configuration is known. Independent Render-Encode-Decode semantic attribution is not certified by configuration presence. Primary composite observations and controlled components are tracked in separate reports.'})
result={'schema':1,'releaseSourceCommit':s['finalSourceCommit'],'artifacts':artifacts,'selectedCutSettings':units,'artifactCount':len(artifacts),'cutSettingCount':len(units),'settingsAreIndependentEffects':False,'populationLimit':'This is the complete actual selected 30-movie cut configuration ledger, with original source labels retained for23 scoped reused movies. It is not a claim that each nonzero parameter constitutes a separately active intent, nor an independent effect realization denominator. New final-source movies require a new ledger after selection.','QUALITY_GO':'UNVERIFIED','human':'HUMAN_UNVERIFIED'};(R/'final-selected-direction-intent-ledger.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:result[k] for k in ['artifactCount','cutSettingCount','settingsAreIndependentEffects']}))
